package primitives

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"maps"
	"path"
	"slices"
	"strconv"
	"strings"
)

// ImportsTestFile is the generated test each package under an imports
// rule carries.
const ImportsTestFile = "primitives_imports_test.go"

// Generate renders every generated file, keyed by repo-relative path.
func (c *Registry) Generate() (map[string][]byte, error) {
	module, err := modulePath(c.fsys)
	if err != nil {
		return nil, err
	}
	type ban struct{ deny, primitive, why, instead string }
	byPkg := map[string][]ban{}
	for _, p := range c.Primitives {
		for _, rule := range p.Imports {
			for _, from := range rule.From {
				byPkg[from.Value] = append(byPkg[from.Value], ban{path.Join(module, rule.Deny), p.ID, rule.Why, rule.Instead})
			}
		}
	}
	out := map[string][]byte{}
	for _, dir := range slices.Sorted(maps.Keys(byPkg)) {
		pkg, err := packageName(c.fsys, dir)
		if err != nil {
			return nil, err
		}
		bans := byPkg[dir]
		slices.SortFunc(bans, func(a, b ban) int { return strings.Compare(a.deny+a.primitive, b.deny+b.primitive) })
		var b bytes.Buffer
		fmt.Fprintf(&b, "// Code generated by cmd/primitives from %s/; DO NOT EDIT.\n\npackage %s_test\n\n", Dir, pkg)
		b.WriteString("import (\n\t\"os/exec\"\n\t\"strings\"\n\t\"testing\"\n)\n\n")
		b.WriteString("func TestPrimitiveImports(t *testing.T) {\n")
		b.WriteString("\tout, err := exec.Command(\"go\", \"list\", \"-deps\", \".\").CombinedOutput()\n")
		b.WriteString("\tif err != nil {\n\t\tt.Fatalf(\"go list -deps: %v\\n%s\", err, out)\n\t}\n")
		b.WriteString("\tdeps := map[string]bool{}\n")
		b.WriteString("\tfor line := range strings.SplitSeq(string(out), \"\\n\") {\n\t\tdeps[strings.TrimSpace(line)] = true\n\t}\n")
		b.WriteString("\tfor _, ban := range []struct{ deny, primitive, why, instead string }{\n")
		for _, x := range bans {
			fmt.Fprintf(&b, "\t\t{%s, %s, %s, %s},\n", strconv.Quote(x.deny), strconv.Quote(x.primitive), strconv.Quote(x.why), strconv.Quote(x.instead))
		}
		b.WriteString("\t} {\n\t\tif deps[ban.deny] {\n")
		b.WriteString("\t\t\tt.Errorf(\"this package links %s, which primitive %s forbids.\\nWhy: %s\\nInstead: %s\", ban.deny, ban.primitive, ban.why, ban.instead)\n")
		b.WriteString("\t\t}\n\t}\n}\n")
		src, err := format.Source(b.Bytes())
		if err != nil {
			return nil, fmt.Errorf("format %s: %w", dir, err)
		}
		out[path.Join(dir, ImportsTestFile)] = src
	}
	return out, nil
}

// Stale compares the generated files with the tree: a path maps to
// "missing", "outdated", or "orphaned" (on disk, no longer generated).
func (c *Registry) Stale() (map[string]string, error) {
	want, err := c.Generate()
	if err != nil {
		return nil, err
	}
	stale := map[string]string{}
	for _, rel := range slices.Sorted(maps.Keys(want)) {
		got, err := fs.ReadFile(c.fsys, rel)
		switch {
		case errors.Is(err, fs.ErrNotExist):
			stale[rel] = "missing"
		case err != nil:
			return nil, err
		case !bytes.Equal(got, want[rel]):
			stale[rel] = "outdated"
		}
	}
	err = fs.WalkDir(c.fsys, ".", func(rel string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			switch d.Name() {
			case ".git", "node_modules", "dist", "testdata":
				return fs.SkipDir
			}
			return nil
		}
		if d.Name() != ImportsTestFile {
			return nil
		}
		if _, ok := want[rel]; !ok {
			stale[rel] = "orphaned"
		}
		return nil
	})
	return stale, err
}

func modulePath(fsys fs.FS) (string, error) {
	src, err := fs.ReadFile(fsys, "go.mod")
	if err != nil {
		return "", err
	}
	for line := range strings.SplitSeq(string(src), "\n") {
		if mod, ok := strings.CutPrefix(strings.TrimSpace(line), "module "); ok {
			return strings.TrimSpace(mod), nil
		}
	}
	return "", fmt.Errorf("go.mod names no module")
}

func packageName(fsys fs.FS, dir string) (string, error) {
	files, err := fs.Glob(fsys, path.Join(dir, "*.go"))
	if err != nil {
		return "", err
	}
	for _, f := range files {
		if strings.HasSuffix(f, "_test.go") {
			continue
		}
		src, err := fs.ReadFile(fsys, f)
		if err != nil {
			return "", err
		}
		parsed, err := parser.ParseFile(token.NewFileSet(), f, src, parser.PackageClauseOnly)
		if err != nil {
			return "", err
		}
		return parsed.Name.Name, nil
	}
	return "", fmt.Errorf("%s holds no Go package", dir)
}
